formulas.expression:
IF(
AND(
/* Must always be New */
        CONTAINS(TEXT({!Get_Final_Quote_Data.SBQQ__Opportunity2__r.Type}), "New"),
    OR(
        /* Business Motion is NOT MSP, Deployment is OnPrem */
        AND(
            NOT(ISPICKVAL({!Get_Final_Quote_Data.SBQQ__Opportunity2__r.Business_Motion__c}, 'MSP')),
            NOT({!Get_Final_Quote_Data.Deployment_Exception_Granted__c}),
            ISPICKVAL({!Get_Final_Quote_Data.Deployment_Method__c}, 'OnPrem'),
            NOT({!Get_Final_Quote_Data.Deployment_Partner__r.On_Prem_Deployment_Verified__c})
        ),
        /* Business Motion is NOT MSP, Deployment is Cloud */
        AND(
            NOT(
                OR(
                    {!Get_Final_Quote_Data.Deployment_Partner__r.Cloud_Deployment_Verified__c},
                    {!Get_Final_Quote_Data.Deployment_Partner__r.MSP_EM_RS_Accredited__c}
                )
            ),
            NOT(ISPICKVAL({!Get_Final_Quote_Data.SBQQ__Opportunity2__r.Business_Motion__c}, 'MSP')),
            NOT({!Get_Final_Quote_Data.Deployment_Exception_Granted__c}),
            CONTAINS(TEXT({!Get_Final_Quote_Data.Deployment_Method__c}), 'Cloud'),
            OR(
                NOT({!Get_Final_Quote_Data.Deployment_Partner__r.Cloud_Deployment_Verified__c}),
                NOT({!Get_Final_Quote_Data.Deployment_Partner__r.MSP_EM_RS_Accredited__c})
            )
        )
    )),
    TRUE,
    FALSE
)

IF(
    AND(
        /* Must always be New */
        CONTAINS(TEXT({!Get_Quote.SBQQ__Opportunity2__r.Type}), "New"),

        OR(
            /* Business Motion is NOT MSP, Deployment is OnPrem */
            AND(
                NOT(ISPICKVAL({!Get_Quote.SBQQ__Opportunity2__r.Business_Motion__c}, "MSP")),
