            ),

            /* Business Motion is NOT MSP, Deployment is Cloud */
            AND(
                NOT(
                    OR(
                        {!Get_Quote.Deployment_Partner__r.Cloud_Deployment_Verified__c},
                        {!Get_Quote.Deployment_Partner__r.MSP_EM_RS_Accredited__c}
